SELECT ROUND(100.0 * SUM(CASE WHEN label = '+' THEN 1 ELSE 0 END) / COUNT(*), 3) AS carcinogenic_percentage
FROM molecule
LIMIT 200;

SELECT COUNT(*) AS post_count
FROM posts
WHERE OwnerUserId = (
    SELECT Id FROM users WHERE DisplayName = 'csgillespie'
)
LIMIT 200;

